INSERT INTO feature VALUES('string-model','effects','A string written in the language','temporary-access','partial','uncommon','mainstream languages','A string written as a corpus subject in the language itself: its bytes inline up to a capacity or in a buffer with a holder count, UTF-8 encoding of code points, a trailing zero for a C reading refused at an interior zero, copy-on-write that copies a buffer only when another string holds it, the in-place write a one-holder string licenses, and views lent by an access or kept in the region of a scope around it. The builtin `String` is not yet replaced by it.','surface-corpus surface-dispatcher','corpus/model/strings/string-base.gandr corpus/model/strings/copy-on-write.gandr corpus/model/strings/views.gandr corpus/pathological/strings/views.gandr','corpus/ledger/features/string-model.gandr','#3555');
